def idf_weighted(q, d, norm='sum'):
    a, b = bigrams(q), bigrams(question_of(d))
    shared = a & b
    if not shared: return 0.0
    num = sum(math.log((N+1)/(df[g]+1)) for g in shared)
    if norm=='sum': return num/len(a|b)
    if norm=='cos': return num/math.sqrt(max(1,len(a))*max(1,len(b)))
    return num
def rank_metrics(order_fn, k_list=(1,3,5,10,20,50)):
